    octFaqBadge: "<i class=\"fas fa-question-circle\"></i> الأسئلة الشائعة عن مكتب 6 أكتوبر",
    octFaqTitle: "أسئلة شائعة حول مكتب المحاماة في 6 أكتوبر",
    octFaqDesc: "إجابات سريعة على أكثر الاستفسارات تكراراً حول مكتبنا في مول الحجاز",
    octFaq1Q: "أين يقع مكتب المحاماة في 6 أكتوبر بالتحديد؟",
    octFaq1A: "مكتب مؤسسة الغنيمي للمحاماة يقع في <strong>مول الحجاز بالقرب من ميدان الحصري</strong> بمدينة 6 أكتوبر، الجيزة. الموقع استراتيجي وسهل الوصول من جميع أحياء 6 أكتوبر (الحي الأول للعاشر، الحي المتميز، حي الأشجار، غرب سوميد) ومن الشيخ زايد القريبة جداً.",
    octFaq2Q: "ما هي المحاكم التي يترافع أمامها محامو مكتب 6 أكتوبر؟",
    octFaq2A: "محامو مكتب 6 أكتوبر يترافعون أمام: <strong>محكمة 6 أكتوبر الابتدائية</strong> (مدنية، تجارية، إدارية)، <strong>محكمة 6 أكتوبر للأسرة</strong> (طلاق، نفقة، حضانة، خلع)، <strong>نيابة 6 أكتوبر الكلية والجزئية</strong> (تحقيقات جنائية)، <strong>محكمة الشيخ زايد للأسرة</strong>، <strong>نيابة الشيخ زايد</strong>، <strong>محكمة استئناف الجيزة</strong>، و<strong>محكمة النقض</strong> للطعون.",
    octFaq3Q: "ما هي مواعيد عمل مكتب المحاماة في 6 أكتوبر؟",
    octFaq3A: "مكتب 6 أكتوبر في مول الحجاز يعمل <strong>يومياً من الساعة 5:00 مساءً حتى 10:00 مساءً</strong>. كما نوفر <strong>استشارات أونلاين 24/7</strong> عبر واتساب، زوم، ومكالمات الفيديو للعملاء في جميع المحافظات وخارج مصر.",
    octFaq4Q: "هل تقدمون خدمات لسكان الشيخ زايد من مكتب 6 أكتوبر؟",
    octFaq4A: "<strong>نعم بالتأكيد</strong>. مكتب 6 أكتوبر في مول الحجاز يبعد دقائق قليلة عن الشيخ زايد، ونخدم سكان <strong>الشيخ زايد الجديدة والقديمة</strong>، الحي الأول والثاني والثالث والرابع، <strong>البشاير</strong>، <strong>الياسمين</strong>، <strong>كايرو جيت</strong>، <strong>الربوة</strong>. نترافع أمام <strong>محكمة الشيخ زايد للأسرة</strong> و<strong>نيابة الشيخ زايد</strong> بشكل مستمر.",
    octFaq5Q: "كيف أحجز موعد في مكتب 6 أكتوبر؟",
    octFaq5A: "يمكنك حجز موعد بسهولة: <strong>1)</strong> تواصل عبر واتساب 01126118276 (رد فوري)، <strong>2)</strong> اتصل 01003651199 (يومياً 5-10 مساءً)، <strong>3)</strong> املأ نموذج الحجز الإلكتروني، <strong>4)</strong> احضر للمكتب في <strong>مول الحجاز - ميدان الحصري</strong> في الموعد المحدد.",
    octFaq6Q: "هل يمكنكم تمثيلي أمام محكمة النقض من مكتب 6 أكتوبر؟",
    octFaq6A: "<strong>نعم</strong>. محامو مؤسسة الغنيمي متخصصون في <strong>الطعن بالنقض</strong> ويمثلون العملاء أمام <strong>محكمة النقض</strong> بشكل مستمر. نعد مذكرات طعن قوية ومستندة لأحدث الأحكام والمبادئ، ونمتلك خبرة 19+ سنة في الترافع أمام محكمة النقض.",
    octFaq7Q: "هل تخدمون مناطق أخرى غير 6 أكتوبر من هذا المكتب؟",
    octFaq7A: "<strong>نعم</strong>. مكتب 6 أكتوبر في مول الحجاز يخدم: <strong>جميع أحياء 6 أكتوبر</strong>، <strong>الشيخ زايد</strong>، <strong>الجيزة</strong> (الدقي، المهندسين، العجوزة، إمبابة، الهرم، فيصل)، <strong>القاهرة</strong> (وسط البلد، مصر الجديدة، مدينة نصر، المعادي، التجمع)، و<strong>جميع محافظات مصر عن بُعد</strong>.",
    octCtaHeading: "محتاج محامي في 6 أكتوبر؟ ابدأ بخطوة واضحة",
    octCtaSub: "مكتب مؤسسة الغنيمي في مول الحجاز جاهز لخدمتك. محامون متخصصون، خبرة 19+ سنة، تمثيل أمام جميع المحاكم.",
