    zayedFaq1Q: "هل لديكم مكتب فعلي في الشيخ زايد؟",
    zayedFaq1A: "مكتبنا الرئيسي في <strong>6 أكتوبر - مول الحجاز - ميدان الحصري</strong>، ويبعد <strong>دقائق معدودة</strong> عن الشيخ زايد. نخدم سكان الشيخ زايد بالكامل من مكتب 6 أكتوبر، ونترافع يومياً أمام <strong>محكمة الشيخ زايد للأسرة</strong> و<strong>نيابة الشيخ زايد</strong>.",
    zayedFaq2Q: "ما هي الأحياء التي تخدمونها في الشيخ زايد؟",
    zayedFaq2A: "نخدم جميع أحياء الشيخ زايد: <strong>الشيخ زايد الجديدة</strong>، <strong>الشيخ زايد القديمة</strong>، <strong>الحي الأول</strong>، <strong>الحي الثاني</strong>، <strong>الحي الثالث</strong>، <strong>الحي الرابع</strong>، <strong>البشاير</strong>، <strong>الياسمين</strong>، <strong>كايرو جيت</strong>، <strong>الربوة</strong>.",
    zayedFaq3Q: "هل تترافعون أمام محكمة الشيخ زايد للأسرة؟",
    zayedFaq3A: "<strong>نعم يومياً</strong>. محامونا يترافعون أمام <strong>محكمة الشيخ زايد للأسرة</strong> بشكل يومي في جميع قضايا الأحوال الشخصية: <strong>الطلاق</strong>، <strong>الخلع</strong>، <strong>النفقة</strong>، <strong>الحضانة</strong>، <strong>الرؤية</strong>.",
    zayedFaq4Q: "هل تخدمون نيابة الشيخ زايد في القضايا الجنائية؟",
    zayedFaq4A: "<strong>نعم</strong>. نترافع أمام <strong>نيابة الشيخ زايد</strong> في جميع أنواع القضايا الجنائية: <strong>التحقيقات</strong>، <strong>الجنح</strong>، <strong>الجنايات</strong>، <strong>المخالفات</strong>.",
