    zayedFaq6Q: "هل تقدمون استشارات أونلاين لسكان الشيخ زايد؟",
    zayedFaq6A: "<strong>نعم</strong>. نقدم <strong>استشارات قانونية كاملة أونلاين</strong> عبر <strong>زوم</strong>، <strong>واتساب</strong>، <strong>مكالمة هاتفية</strong>. لا داعي للحضور للمكتب.",
    zayedFaq7Q: "هل تخدمون سكان البشاير والياسمين وكايرو جيت والربوة؟",
