    area6Title: "جميع محافظات مصر (عن بُعد)",
    area6Desc: "نقدم الاستشارات القانونية أونلاين ونمثّل العملاء في جميع محاكم الجمهورية عبر فريقنا المنتشر. تواصل معنا عبر واتساب أو احجز استشارة أونلاين.",
