    svcFamilyArea2Service1: "<i class=\"fas fa-check\"></i> نفقة وحضانة ورؤية الشيخ زايد",
    svcFamilyArea2Service2: "<i class=\"fas fa-check\"></i> طلاق وخلع الشيخ زايد",
