    faq1Q: "How do I choose the right lawyer for my case?",
    faq1A: "Choosing a lawyer depends on the case type: criminal cases need a criminal & cassation specialist, family cases need a personal status lawyer, real estate needs a real estate & land registry lawyer. Al-Ghonemy has an integrated team covering all specialties. We start by studying your case then guide you to the most suitable lawyer.",
    faq2Q: "What is the cost of a legal consultation?",
    faq2A: "Consultation cost varies by case type and complexity. We offer an initial consultation at competitive prices with full cost transparency before starting. We believe in transparency: no hidden fees. Contact us for a custom quote for your case.",
    faq3Q: "Do you offer online legal consultations?",
    faq3A: "Yes, we provide full online legal consultations via Zoom, WhatsApp, or phone call. We serve clients in all Egyptian governorates and abroad. We send contracts and documents electronically and sign digitally. Book your online consultation from the booking page or contact us via WhatsApp.",
    faq4Q: "How long does a divorce or khula case take?",
    faq4A: "Divorce duration varies: mutual consent divorce may take 1-3 months, fault-based divorce 6-18 months, khula 3-6 months. Duration depends on party cooperation, evidence documents, and court schedule. Al-Ghonemy lawyers expedite procedures by preparing strong documents from the start.",
    faq5Q: "What are the land registry procedures for property in 6th of October?",
    faq5A: "Land registry in 6th of October: 1) Prepare official contract, 2) Pay fees and taxes, 3) Submit application to 6th of October or Sheikh Zayed Land Registry, 4) Document review, 5) Registration and receipt. Al-Ghonemy handles all procedures from A to Z.",
    faq6Q: "How do I protect my inheritance rights if heirs refuse division?",
    faq6A: "If heirs refuse division: 1) File a forced partition lawsuit before Family Court, 2) Request court-appointed expert to evaluate estate, 3) Request property sale and proceeds division if physical division impossible. Al-Ghonemy specializes in inheritance & estates, achieving best results for heirs.",
    faq7Q: "What are the steps to form a company in Egypt 2026?",
    faq7A: "Company formation in 2026: 1) Choose company type (Single Person, LLC, Joint-Stock), 2) Reserve trade name, 3) Prepare Memorandum & Articles of Association, 4) Deposit capital in bank, 5) Register in Commercial Registry, 6) Obtain Tax Card & Commercial Register, 7) Register in Social Insurance. Al-Ghonemy completes formation in 7-14 business days.",
    faq8Q: "How do I contact Al-Ghonemy Law Firm?",
    faq8A: "You can contact us via: <strong>WhatsApp</strong>: <a href=\"https://wa.me/201126118276\">+20 112 611 8276</a>, <strong>Phone</strong>: <a href=\"tel:+201003651199\">+20 100 365 1199</a>, <strong>Email</strong>: <a href=\"mailto:alghoneimy.Law@gmail.com\">alghoneimy.Law@gmail.com</a>, <strong>Office</strong>: Al Hejaz Mall – Near Al-Hosary Square – 6th of October – Giza. We work daily 5 PM - 10 PM.",
    svcCriminalBreadcrumb: "Criminal Cases",
    svcCriminalTitle: "Lawyer جنائي في 6th of October، Sheikh Zayed، Giza | Criminal Cases وCassation",
    svcCriminalDesc: "تمثيل قانوني أمام المحاكم الجنائية، الFelonies الكبرى، Court Cassation، الAppeal، الProsecution العامة. دفاع متخصص في الMisdemeanors، الFelonies، Cassation Appeals، مذكرات دفاع في 6th of October، Sheikh Zayed، Giza، Cairo.",
    svcCriminalContent1: "Criminal Cases من أخطر المجالات القانونية التي تمس حرية الإنسان وسمعته ومستقبله. Al-Ghonemy Law Firm للمحاماة تقدم تمثيلاً قانونياً متكاملاً أمام جميع المحاكم الجنائية في 6th of October، Sheikh Zayed، Giza، Cairo، وجميع محافظات مصر.",
    svcCriminalContent2: "نمتلك خبرة تمتد لأكثر من 19 عاماً في الدفاع أمام المحاكم الجنائية، الFelonies الكبرى، محاكم الAppeal، وCourt Cassation. ندرس كل تفصيل في ملف القضية، نحدد نقاط القوة والضعف، ونبني استراتيجية دفاعية Court.",
    svcCriminalContent3: "نخدم الEmploymentاء في جميع أنحاء 6th of October (الحي الأول إلى العاشر، الحي المتميز، غرب سوميد)، Sheikh Zayed (الجديدة، القديمة، البشاير، الياسمين، كايرو جيت)، Giza (الدقي، المهندسين، العجوزة، إمبابة، الهرم، فيصل، بولاق الدكرور)، Cairo (وسط البلد، مدينة نصر، المعادي، التجمع الخامس، الرحاب، مدينتي، الشروق، العبور)، وجميع محافظات مصر.",
    svcCriminalScopeTitle: "<i class=\"fas fa-balance-scale-right gold-icon\"></i> نطاق الخدمة الجنائية الشاملة",
