    svcCriminalScope2: "<i class=\"fas fa-check-circle\"></i> <strong>الدفاع في قضايا الFelonies الكبرى:</strong> القتل، السرقة بالإكراه، المخدرات، الأسلحة، الإرهاب، غسل الأموال",
    svcCriminalScope3: "<i class=\"fas fa-check-circle\"></i> <strong>الدفاع في قضايا الMisdemeanors والمخالفات:</strong> الشيكات، السب والقذف، التعدي، المرور، البلاغات الكاذبة",
    svcCriminalScope4: "<i class=\"fas fa-check-circle\"></i> <strong>صياغة مذكرات الدفاع وأسباب Cassation Appeals:</strong> دراسة ملف القضية، استخراج الدفوع القانونية، صياغة بأسلوب قانوني راقٍ",
    svcCriminalScope5: "<i class=\"fas fa-check-circle\"></i> <strong>حضور التحقيقات أمام الProsecution العامة:</strong> حضور من أول جلسة، إثبات الدفوع، حماية حقوق المتهم",
    svcCriminalScope6: "<i class=\"fas fa-check-circle\"></i> <strong>الAppeal في الأحكام الجنائية:</strong> Appeal الأحكام الحضورية والغيابية، مذكرات Appeal، حضور الجلسات",
    svcCriminalScope7: "<i class=\"fas fa-check-circle\"></i> <strong>المعارضة في الأحكام الغيابية:</strong> تقديم المعارضة في الميعاد، إعادة المحاكمة، حضور الجلسات",
    svcCriminalScope8: "<i class=\"fas fa-check-circle\"></i> <strong>الدفوع الشكلية والموضوعية:</strong> الدفع ببطلان الإجراءات، انتفاء القصد الجنائي، انتفاء الركن المادي، الدفع بالتقادم",
    svcCriminalScope9: "<i class=\"fas fa-check-circle\"></i> <strong>إجراءات إخلاء السبيل:</strong> طلبات إخلاء السبيل، الضمان المالي، الضمان الشخصي، بدائل الحبس الاحتياطي",
    svcCriminalScope10: "<i class=\"fas fa-check-circle\"></i> <strong>Cybercrime والمعلوماتية:</strong> الابتزاز الإلكتروني، الHacking، الDefamation، جرائم البطاقات البنكية",
