    svcCriminalArea4Desc: "<strong>المحاكم:</strong> Court Cairo الابتدائية، Appeal Cairo، Court Cassation، Court Felonies Cairo، Prosecution Cairo الكلية، نيابات الأقسام (مدينة نصر، المعادي، التجمع، شبرا، الزيتون، بولاق، باب الشعرية، عابدين، عابدين).",
