    svcFamilyArea3Desc: "<strong>الاختصاص:</strong> الدقي، المهندسين، العجوزة، إمبابة، الهرم، فيصل، بولاق الدكرور، الوراق، كرداسة، أوسيم، أطفيح، البدرشين.",
