    svcInheritanceArea4Title: "Court أسرة Cairo",
    svcInheritanceArea4Desc: "<strong>الاختصاص:</strong> جميع أحياء Cairo (التجمع، المعادي، مدينة نصر، الرحاب، مدينتي، الشروق، العبور).",
    svcInheritanceArea4Service1: "<i class=\"fas fa-check\"></i> ميراث Cairo الكبرى",
    svcInheritanceArea4Service2: "<i class=\"fas fa-check\"></i> تركات معقدة (Companies، أسهم)",
    svcInheritanceArea4Service3: "<i class=\"fas fa-check\"></i> وصايا ووصية واجبة",
    svcInheritanceArea4Service4: "<i class=\"fas fa-check\"></i> تركات ذات طابع دولي",
    svcInheritanceFaqBadge: "<i class=\"fas fa-question-circle\"></i> FAQ في الميراث",
    svcInheritanceFaqDesc: "إجابات على أكثر الاستفسارات تكراراً. لم تجد إجابتك؟ <a class=\"link-inline\" href=\"../contact.html\">Contact معنا مباشرة</a>.",
    svcInheritanceFaq1Q: "ما هي المستندات المطلوبة لاستخراج Heir Notification؟",
    svcInheritanceFaq1A: "المستندات المطلوبة: شهادة الوفاة، صورة بطاقة الرقم القومي للمتوفى، قسيمة الزواج/الDivorce، شهادات ميلاد الورثة، مستندات ملكية التركة (عقود، شهادات)، توكيل رسمي للLawyer. Al-Ghonemy Law Firm تتولى جمع وتجهيز جميع المستندات.",
    svcInheritanceFaq2Q: "كم تستغرق إجراءات استخراج Heir Notification؟",
    svcInheritanceFaq2A: "إجراءات Heir Notification تستغرق عادة من 2 إلى 4 أسابيع في حال عدم وجود نزاع، وتطول المدة في حال وجود نزاع بين الورثة أو طعن في التركة. Al-Ghonemy Law Firm تسرع الإجراءات بمتابعة يومية.",
    svcInheritanceFaq3Q: "ماذا لو امتنع بعض الورثة عن Division التركة؟",
    svcInheritanceFaq3A: "إذا امتنع الورثة عن الDivision التراضي، ترفع دعوى Division إجبار أمام الCourt المختصة. الCourt تعين خبيراً لتقييم التركة وتقسيمها، أو تأمر ببيع العقار وتوزيع الثمن إذا تعذر الDivision عيناً. Al-Ghonemy Law Firm تتولى دعوى الDivision الإجبار من الألف للياء.",
    svcInheritanceFaq4Q: "ما هي حقوق الزوجة في الميراث؟",
    svcInheritanceFaq4A: "الزوجة ترث الربع إذا لم يكن هناك فرع وارث (أولاد)، والثمن إذا وجد فرع وارث. إذا تعدد الزوجات يقسم الثمن أو الربع بينهن بالتساوي. Al-Ghonemy Law Firm تضمن حق الزوجة في الميراث كاملاً.",
    svcInheritanceFaq5Q: "كيف يتم Correction Heir Notification إذا كان به خطأ؟",
    svcInheritanceFaq5A: "يتم رفع دعوى Correction إعلام وراثة أمام الCourt التي أصدرته، مع تقديم المستندات الدالة على الخطأ (شهادات ميلاد، قسائم زواج/Divorce، مستندات ملكية). Al-Ghonemy Law Firm تتولى دعوى الCorrection بجميع إجراءاتها.",
    svcInheritanceFaq6Q: "ماذا لو كانت هناك وصية للمتوفى؟",
    svcInheritanceFaq6A: "الوصية الشرعية تنفذ في حدود الثلث من التركة، ولا تورث وارثاً. إذا جاوزت الثلث ولم يجز الورثة الزيادة، تنفذ في الثلث فقط. Al-Ghonemy Law Firm تتولى تنفيذ الوصايا الشرعية والشرطية وحماية حقوق الموصى لهم.",
    svcInheritanceFaq7Q: "كيف تتم Division التركة إذا كان فيها عقارات؟",
    svcInheritanceFaq7A: "إذا اتفق الورثة: Division تراضي بتوثيق العقد في Land Registry. إذا اختلفوا: دعوى Division إجبار، الCourt تعين خبيراً لتقييم العقار، فإن أمكنت الDivision عيناً قسّمت، وإلا بيع العقار وقُسّم الثمن. Al-Ghonemy Law Firm تتولى الDivision تراضياً وقضائياً.",
    svcInheritanceFaq8Q: "ما هي حقوق الحفيد في الميراث (الوصية الواجبة)؟",
    svcInheritanceFaq8A: "الوصية الواجبة: للحفيد من الابن المتوفى قبل أبيه (أو معه) حق في الميراث بقدر ما كان سيرث أبوه لو عاش، في حدود الثلث. تشترط: وفاة الأب قبل الجد، وعدم وراثة الحفيد من جهة أخرى. Al-Ghonemy Law Firm تدافع عن حق الأحفاد في الوصية الواجبة.",
    svcInheritanceCtaHeading: "تواجه نزاعاً في الميراث أو تحتاج لإعلام وراثة سريع؟",
    svcInheritanceCtaSub: "فريقنا الميراثي جاهز لمساعدتك في 6th of October، Sheikh Zayed، Giza، Cairo. Confidentiality – سرعة – نتائج.",
    svcRealEstateBreadcrumb: "Real Estate Cases",
    svcRealEstateTitle: "Lawyer قضايا عقارات في 6th of October",
    svcRealEstateDesc: "Real Estate Cases قد ترتبط بعقود أو ملكية أو تسجيل أو نزاعات بين الأطراف، ولذلك تحتاج إلى مراجعة دقيقة للمستندات والوقائع قبل اتخاذ أي إجراء. تقدم Al-Ghonemy Law Firm خدمات قانونية متعلقة بالDisputes العقارية، وContract Drafting & Review، والمسائل المرتبطة بالملكية والتسجيل وValidation العقود وغيرها من المسائل العقارية.",
