    faq6Q: "How do I protect my inheritance rights if heirs refuse division?",
    faq6A: "If heirs refuse division: 1) File a forced partition lawsuit before Family Court, 2) Request court-appointed expert to evaluate estate, 3) Request property sale and proceeds division if physical division impossible. Al-Ghonemy specializes in inheritance & estates, achieving best results for heirs.",
    faq7Q: "What are the steps to form a company in Egypt 2026?",
    faq7A: "Company formation in 2026: 1) Choose company type (Single Person, LLC, Joint-Stock), 2) Reserve trade name, 3) Prepare Memorandum & Articles of Association, 4) Deposit capital in bank, 5) Register in Commercial Registry, 6) Obtain Tax Card & Commercial Register, 7) Register in Social Insurance. Al-Ghonemy completes formation in 7-14 business days.",
    faq8Q: "How do I contact Al-Ghonemy Law Firm?",
