    svcCriminalDesc: "Representation before 6th of October Court, Giza Appeal, Court of Cassation. Misdemeanors, felonies, appeals, strong defense.",
    svcCriminalContent1: "Criminal cases are among the most critical legal fields requiring expertise and precision in handling every detail. Al-Ghonemy Law Firm provides legal representation services before criminal courts and major felony courts.",
    svcCriminalContent2: "Our scope includes: cassation appeals in criminal judgments, drafting defense briefs, studying facts and documents, and representing clients before competent courts.",
