    svcCriminalFaqBadge: "FAQ - Criminal Cases",
    svcCriminalFaqDesc: "Quick answers to most frequent inquiries about criminal cases",
    svcCriminalFaq1Q: "What is the legal deadline for cassation appeal?",
    svcCriminalFaq1A: "Cassation appeal is filed within 60 days from the judgment date in criminal matters.",
    svcCriminalFaq2Q: "Can a lawyer be appointed after judgment?",
    svcCriminalFaq2A: "Yes, a lawyer can be appointed to appeal the judgment within the legal deadline.",
    svcCriminalFaq3Q: "What is the difference between misdemeanor and felony?",
    svcCriminalFaq3A: "Misdemeanor penalty is imprisonment up to 3 years; felony penalty is rigorous imprisonment, life imprisonment, or death.",
    svcCriminalFaq4Q: "Can an absentia judgment be appealed?",
    svcCriminalFaq4A: "Yes, objection to absentia judgment can be filed within 10 days of notification.",
    svcCriminalFaq5Q: "What are prosecution investigation procedures?",
    svcCriminalFaq5A: "Investigation includes hearing statements, confronting witnesses, and inspection. The accused has right to silence and right to counsel.",
    svcCriminalFaq6Q: "How is misdemeanor appeal filed?",
    svcCriminalFaq6A: "Appeal is filed within 10 days of judgment, before Giza Court of Appeal.",
    svcCriminalFaq7Q: "What are accused rights in investigation?",
    svcCriminalFaq7A: "Right to silence, right to counsel, right not to self-incriminate, right to know charges.",
    svcCriminalFaq8Q: "Do you serve 6th of October Public Prosecution?",
    svcCriminalFaq8A: "Yes, we appear before 6th of October General and Partial Prosecution in all criminal case types.",
    svcCriminalFaq9Q: "What is criminal reconciliation?",
    svcCriminalFaq9A: "Criminal reconciliation is a legal mechanism to resolve certain misdemeanors by agreement between parties with court approval.",
    svcCriminalCtaHeading: "Need a Criminal Lawyer in 6th of October or Giza?",
