    octFaqBadge: "<i class=\"fas fa-question-circle\"></i> FAQ about 6th of October Office",
    octFaqTitle: "Frequently Asked Questions about Our 6th of October Law Office",
    octFaqDesc: "Quick answers to most common inquiries about our Al Hejaz Mall office",
    octFaq1Q: "Where exactly is the law office in 6th of October?",
    octFaq1A: "Al-Ghonemy Law Firm office is located at <strong>Al Hejaz Mall near Al-Hosary Square</strong> in 6th of October City, Giza. Strategic location easily accessible from all 6th of October districts and nearby Sheikh Zayed.",
    octFaq2Q: "Which courts do your 6th of October lawyers appear before?",
    octFaq2A: "Our lawyers appear before: <strong>6th of October Primary Court</strong>, <strong>6th of October Family Court</strong>, <strong>6th of October General & Partial Prosecution</strong>, <strong>Sheikh Zayed Family Court</strong>, <strong>Sheikh Zayed Prosecution</strong>, <strong>Giza Court of Appeal</strong>, and <strong>Court of Cassation</strong>.",
    octFaq3Q: "What are the working hours of the 6th of October office?",
    octFaq3A: "6th of October office at Al Hejaz Mall operates <strong>daily from 5:00 PM to 10:00 PM</strong>. We also provide <strong>24/7 online consultations</strong> via WhatsApp, Zoom, and video calls.",
    octFaq4Q: "Do you provide services for Sheikh Zayed residents from 6th of October office?",
    octFaq4A: "<strong>Yes absolutely</strong>. 6th of October office is minutes away from Sheikh Zayed, serving <strong>New & Old Sheikh Zayed</strong>, District 1-4, <strong>Al Bashaer</strong>, <strong>Al Yasmine</strong>, <strong>Cairo Gate</strong>, <strong>Al Rabwa</strong>. We appear before <strong>Sheikh Zayed Family Court</strong> regularly.",
    octFaq5Q: "How to book an appointment at 6th of October office?",
    octFaq5A: "Book easily: <strong>1)</strong> WhatsApp 01126118276 (instant reply), <strong>2)</strong> Call 01003651199 (daily 5-10 PM), <strong>3)</strong> Fill online booking form, <strong>4)</strong> Visit <strong>Al Hejaz Mall - Al-Hosary Square</strong> at the scheduled time.",
    octFaq6Q: "Can you represent me before the Court of Cassation from 6th of October office?",
    octFaq6A: "<strong>Yes</strong>. Al-Ghonemy lawyers specialize in <strong>Cassation appeals</strong> and regularly represent clients before <strong>Court of Cassation</strong>. We prepare strong memoranda with 19+ years experience.",
    octFaq7Q: "Do you serve areas beyond 6th of October from this office?",
    octFaq7A: "<strong>Yes</strong>. Our 6th of October office serves: <strong>All 6th of October districts</strong>, <strong>Sheikh Zayed</strong>, <strong>Giza</strong> (Dokki, Mohandessin, Agouza, Imbaba, Haram, Faisal), <strong>Cairo</strong> (Downtown, Heliopolis, Nasr City, Maadi, New Cairo) and <strong>all Egypt remotely</strong>.",
