    svcFamilyFaqDesc: "Quick answers to most frequent inquiries about family cases",
    svcFamilyFaq1Q: "Which court handles alimony cases?",
    svcFamilyFaq1A: "The competent Family Court is the court of the wife's residence.",
    svcFamilyFaq2Q: "Can alimony amount be modified after judgment?",
    svcFamilyFaq2A: "Yes, an alimony modification suit can be filed when circumstances change.",
    svcFamilyFaq3Q: "What is the difference between divorce and khula?",
    svcFamilyFaq3A: "Divorce is initiated by the husband; khula is initiated by the wife with return of dowry.",
    svcFamilyFaq4Q: "Can custody be changed after judgment?",
    svcFamilyFaq4A: "Yes, custody can be modified when the child's best interests require it.",
    svcFamilyFaq5Q: "What documents are needed for divorce?",
    svcFamilyFaq5A: "Marriage contract, IDs, children's birth certificates, and proof of residence.",
    svcFamilyFaq6Q: "How long does a divorce case take?",
    svcFamilyFaq6A: "Mutual consent divorce: 1-3 months; fault-based divorce: 6-18 months; khula: 3-6 months.",
    svcFamilyFaq7Q: "Can a wife get alimony after khula?",
    svcFamilyFaq7A: "Khula typically involves waiving alimony, but child support remains mandatory.",
    svcFamilyFaq8Q: "Do you serve Sheikh Zayed Family Court?",
    svcFamilyFaq8A: "Yes, we appear daily before Sheikh Zayed Family Court for all personal status cases.",
