    svcInheritanceFaq3Q: "Can an heir be disinherited?",
    svcInheritanceFaq3A: "Sharia law defines mandatory shares; disinheritance is only possible in specific legal cases.",
    svcInheritanceFaq4Q: "What if heirs disagree on division?",
    svcInheritanceFaq4A: "Court appoints experts to evaluate and divide; property may be sold and proceeds divided.",
    svcInheritanceFaq5Q: "Can a will override Sharia shares?",
    svcInheritanceFaq5A: "A will can only dispose of up to 1/3 of the estate; mandatory shares are protected.",
    svcInheritanceFaq6Q: "How is property sold in inheritance?",
