    octFaqBadge: "<i class=\"fas fa-question-circle\"></i> FAQ sur le Bureau du 6 Octobre",
    octFaqTitle: "Questions Fréquentes sur Notre Cabinet du 6 Octobre",
    octFaqDesc: "Réponses rapides aux questions les plus fréquentes sur notre bureau du Centre Al Hejaz",
    octFaq1Q: "Où se trouve exactement le cabinet d'avocats au 6 Octobre ?",
    octFaq1A: "Le cabinet Al-Ghonemy est situé au <strong>Centre Al Hejaz près de la Place Al-Hosary</strong> au 6 Octobre, Giza. Emplacement stratégique facilement accessible depuis tous les quartiers du 6 Octobre et de Sheikh Zayed à proximité.",
    octFaq2Q: "Devant quels tribunaux plaident vos avocats du 6 Octobre ?",
    octFaq2A: "Nos avocats plaident devant : <strong>Tribunal de Première Instance du 6 Octobre</strong>, <strong>Tribunal de la Famille du 6 Octobre</strong>, <strong>Parquet Général & Partiel du 6 Octobre</strong>, <strong>Tribunal de la Famille de Sheikh Zayed</strong>, <strong>Parquet de Sheikh Zayed</strong>, <strong>Cour d'Appel de Giza</strong> et <strong>Cour de Cassation</strong>.",
    octFaq3Q: "Quelles sont les heures d'ouverture du bureau du 6 Octobre ?",
    octFaq3A: "Le bureau du 6 Octobre au Centre Al Hejaz fonctionne <strong>tous les jours de 17h00 à 22h00</strong>. Nous fournissons aussi des <strong>consultations en ligne 24/7</strong> via WhatsApp, Zoom et appels vidéo.",
    octFaq4Q: "Fournissez-vous des services aux résidents de Sheikh Zayed depuis le bureau du 6 Octobre ?",
