    svcCriminalContent1: "Affaires Pénales من أخطر المجالات القانونية التي تمس حرية الإنسان وسمعته ومستقبله. Cabinet Al-Ghonemy للمحاماة تقدم تمثيلاً قانونياً متكاملاً أمام جميع المحاكم الجنائية في 6 Octobre، Sheikh Zayed، Giza، Le Caire، وجميع محافظات مصر.",
    svcCriminalContent2: "نمتلك خبرة تمتد لأكثر من 19 عاماً في الدفاع أمام المحاكم الجنائية، الCrimes الكبرى، محاكم الAppel، وTribunal Cassation. ندرس كل تفصيل في ملف القضية، نحدد نقاط القوة والضعف، ونبني استراتيجية دفاعية Tribunal.",
    svcCriminalContent3: "نخدم الTravailاء في جميع أنحاء 6 Octobre (الحي الأول إلى العاشر، الحي المتميز، غرب سوميد)، Sheikh Zayed (الجديدة، القديمة، البشاير، الياسمين، كايرو جيت)، Giza (الدقي، المهندسين، العجوزة، إمبابة، الهرم، فيصل، بولاق الدكرور)، Le Caire (وسط البلد، مدينة نصر، المعادي، التجمع الخامس، الرحاب، مدينتي، الشروق، العبور)، وجميع محافظات مصر.",
