    svcInheritanceArea3Desc: "<strong>الاختصاص:</strong> الدقي، المهندسين، الهرم، فيصل، بولاق، الوراق، كرداسة، أوسيم، البدرشين، أطفيح.",
    svcInheritanceArea3Service1: "<i class=\"fas fa-check\"></i> ميراث وتركة Giza",
    svcInheritanceArea3Service2: "<i class=\"fas fa-check\"></i> Partage إجبار Giza",
    svcInheritanceArea3Service3: "<i class=\"fas fa-check\"></i> Correction إعلام وراثة",
    svcInheritanceArea3Service4: "<i class=\"fas fa-check\"></i> وصية واجبة الأحفاد",
    svcInheritanceArea4Title: "Tribunal أسرة Le Caire",
    svcInheritanceArea4Desc: "<strong>الاختصاص:</strong> جميع أحياء Le Caire (التجمع، المعادي، مدينة نصر، الرحاب، مدينتي، الشروق، العبور).",
    svcInheritanceArea4Service1: "<i class=\"fas fa-check\"></i> ميراث Le Caire الكبرى",
    svcInheritanceArea4Service2: "<i class=\"fas fa-check\"></i> تركات معقدة (Sociétés، أسهم)",
    svcInheritanceArea4Service3: "<i class=\"fas fa-check\"></i> وصايا ووصية واجبة",
    svcInheritanceArea4Service4: "<i class=\"fas fa-check\"></i> تركات ذات طابع دولي",
    svcInheritanceFaqBadge: "<i class=\"fas fa-question-circle\"></i> Questions Fréquentes في الميراث",
    svcInheritanceFaqDesc: "إجابات على أكثر الاستفسارات تكراراً. لم تجد إجابتك؟ <a class=\"link-inline\" href=\"../contact.html\">Contactez معنا مباشرة</a>.",
    svcInheritanceFaq1Q: "ما هي المستندات المطلوبة لاستخراج Notification d'Héritiers؟",
    svcInheritanceFaq1A: "المستندات المطلوبة: شهادة الوفاة، صورة بطاقة الرقم القومي للمتوفى، قسيمة الزواج/الDivorce، شهادات ميلاد الورثة، مستندات ملكية التركة (عقود، شهادات)، توكيل رسمي للAvocat. Cabinet Al-Ghonemy تتولى جمع وتجهيز جميع المستندات.",
    svcInheritanceFaq2Q: "كم تستغرق إجراءات استخراج Notification d'Héritiers؟",
    svcInheritanceFaq2A: "إجراءات Notification d'Héritiers تستغرق عادة من 2 إلى 4 أسابيع في حال عدم وجود نزاع، وتطول المدة في حال وجود نزاع بين الورثة أو طعن في التركة. Cabinet Al-Ghonemy تسرع الإجراءات بمتابعة يومية.",
    svcInheritanceFaq3Q: "ماذا لو امتنع بعض الورثة عن Partage التركة؟",
    svcInheritanceFaq3A: "إذا امتنع الورثة عن الPartage التراضي، ترفع دعوى Partage إجبار أمام الTribunal المختصة. الTribunal تعين خبيراً لتقييم التركة وتقسيمها، أو تأمر ببيع العقار وتوزيع الثمن إذا تعذر الPartage عيناً. Cabinet Al-Ghonemy تتولى دعوى الPartage الإجبار من الألف للياء.",
    svcInheritanceFaq4Q: "ما هي حقوق الزوجة في الميراث؟",
    svcInheritanceFaq4A: "الزوجة ترث الربع إذا لم يكن هناك فرع وارث (أولاد)، والثمن إذا وجد فرع وارث. إذا تعدد الزوجات يقسم الثمن أو الربع بينهن بالتساوي. Cabinet Al-Ghonemy تضمن حق الزوجة في الميراث كاملاً.",
    svcInheritanceFaq5Q: "كيف يتم Correction Notification d'Héritiers إذا كان به خطأ؟",
    svcInheritanceFaq5A: "يتم رفع دعوى Correction إعلام وراثة أمام الTribunal التي أصدرته، مع تقديم المستندات الدالة على الخطأ (شهادات ميلاد، قسائم زواج/Divorce، مستندات ملكية). Cabinet Al-Ghonemy تتولى دعوى الCorrection بجميع إجراءاتها.",
    svcInheritanceFaq6Q: "ماذا لو كانت هناك وصية للمتوفى؟",
    svcInheritanceFaq6A: "الوصية الشرعية تنفذ في حدود الثلث من التركة، ولا تورث وارثاً. إذا جاوزت الثلث ولم يجز الورثة الزيادة، تنفذ في الثلث فقط. Cabinet Al-Ghonemy تتولى تنفيذ الوصايا الشرعية والشرطية وحماية حقوق الموصى لهم.",
    svcInheritanceFaq7Q: "كيف تتم Partage التركة إذا كان فيها عقارات؟",
    svcInheritanceFaq7A: "إذا اتفق الورثة: Partage تراضي بتوثيق العقد في Registre Foncier. إذا اختلفوا: دعوى Partage إجبار، الTribunal تعين خبيراً لتقييم العقار، فإن أمكنت الPartage عيناً قسّمت، وإلا بيع العقار وقُسّم الثمن. Cabinet Al-Ghonemy تتولى الPartage تراضياً وقضائياً.",
    svcInheritanceFaq8Q: "ما هي حقوق الحفيد في الميراث (الوصية الواجبة)؟",
    svcInheritanceFaq8A: "الوصية الواجبة: للحفيد من الابن المتوفى قبل أبيه (أو معه) حق في الميراث بقدر ما كان سيرث أبوه لو عاش، في حدود الثلث. تشترط: وفاة الأب قبل الجد، وعدم وراثة الحفيد من جهة أخرى. Cabinet Al-Ghonemy تدافع عن حق الأحفاد في الوصية الواجبة.",
    svcInheritanceCtaHeading: "تواجه نزاعاً في الميراث أو تحتاج لإعلام وراثة سريع؟",
    svcInheritanceCtaSub: "فريقنا الميراثي جاهز لمساعدتك في 6 Octobre، Sheikh Zayed، Giza، Le Caire. Confidentialité – سرعة – نتائج.",
    svcRealEstateBreadcrumb: "Affaires Immobilières",
    svcRealEstateTitle: "Avocat قضايا عقارات في 6 Octobre",
    svcRealEstateDesc: "Affaires Immobilières قد ترتبط بعقود أو ملكية أو تسجيل أو نزاعات بين الأطراف، ولذلك تحتاج إلى مراجعة دقيقة للمستندات والوقائع قبل اتخاذ أي إجراء. تقدم Cabinet Al-Ghonemy خدمات قانونية متعلقة بالLitiges العقارية، وRédaction & Révision de Contrats، والمسائل المرتبطة بالملكية والتسجيل وValidation العقود وغيرها من المسائل العقارية.",
    svcRealEstateContent1: "Affaires Immobilières في 6 Octobre وGiza تتطلب خبرة خاصة في تعاملات التطوير العقاري والتوثيق القانوني للعقود.",
