    svcContractsTitle: "Rédaction & Révision de Contrats",
    svcContractsDesc: "صياغة Contrats Commerciaux والمدنية بمختلف أنواعها. مراجعة الشروط وحماية المصالح التعاقدية لجميع الأطراف.",
    svcContractsContent1: "العقود هي الأساس القانوني لأي علاقة تجارية أو مدنية. نقدم خدمات Rédaction & Révision de Contrats بمهارة قانونية عالية.",
    svcContractsContent2: "نهتم بدراسة كافة البنود والشروط والالتزامات المتبادلة بين الأطراف بدقة، مع صياغة شروط جزائية واضحة وبنود فض الLitiges بما يضمن تجنب النزاعات المستقبلية الطويلة.",
    svcContractsScopeTitle: "<i class=\"fas fa-file-signature gold-icon\"></i> خدمات Rédaction & Révision de Contrats",
