    svcCorporateBreadcrumb: "الSociétés والقانون التجاري",
    svcCorporateTitle: "الSociétés والقانون التجاري",
    svcCorporateDesc: "Création d'Entreprises، إعداد العقد والنظام الأساسي، التسجيل في السجل التجاري، والصفقات التجارية الكبرى.",
    svcCorporateContent1: "Création d'Entreprises في مصر يتطلب فهماً دقيقاً للإجراءات القانونية والمستندات المطلوبة. نتولى جميع إجراءات التأسيس والتسجيل.",
    svcCorporateContent2: "كما نوفر الدعم القانوني الدوري والمتابعة للSociétés القائمة في صياغة العقود الوظيفية وعقود التوريد والتوزيع، وحضور الجمعيات العمومية، وفض النزاعات التجارية.",
