    how4Num: "04",
    how4Title: "Suivi",
    how4Desc: "Les procédures et exigences juridiques sont traitées selon la nature de chaque affaire.",
    faqTitle: "Questions Fréquentes",
    faq1Q: "Comment choisir le bon avocat pour mon affaire ?",
    faq1A: "Le choix de l'avocat dépend du type d'affaire : pénal nécessite un spécialiste pénal & cassation, familial un avocat en statut personnel, immobilier un avocat immobilier & registre foncier. Al-Ghonemy a une équipe intégrée couvrant toutes les spécialités. Nous commençons par étudier votre dossier puis vous guidons vers l'avocat le plus approprié.",
    faq2Q: "Quel est le coût d'une consultation juridique ?",
    faq2A: "Le coût de la consultation varie selon le type et la complexité de l'affaire. Nous offrons une consultation initiale à des prix compétitifs avec transparence totale des coûts avant de commencer. Nous croyons en la transparence : aucuns frais cachés. Contactez-nous pour un devis personnalisé.",
    faq3Q: "Fournissez-vous des consultations juridiques en ligne ?",
    faq3A: "Oui, nous fournissons des consultations juridiques complètes en ligne via Zoom, WhatsApp ou appel téléphonique. Nous servons les clients dans tous les gouvernorats égyptiens et à l'étranger. Nous envoyons les contrats et documents électroniquement et signons numériquement. Réservez votre consultation en ligne depuis la page de réservation ou contactez-nous via WhatsApp.",
    faq4Q: "Combien de temps dure une affaire de divorce ou de khul' ?",
    faq4A: "La durée du divorce varie : divorce par consentement mutuel 1-3 mois, divorce pour faute 6-18 mois, khul' 3-6 mois. La durée dépend de la coopération des parties, des preuves et du calendrier du tribunal. Les avocats d'Al-Ghonemy accélèrent les procédures en préparant des dossiers solides dès le début.",
    faq5Q: "Quelles sont les procédures du registre foncier pour un bien au 6 Octobre ?",
    faq5A: "Registre foncier au 6 Octobre : 1) Préparer le contrat officiel, 2) Payer les frais et taxes, 3) Soumettre la demande au Registre Foncier du 6 Octobre ou de Sheikh Zayed, 4) Examen des documents, 5) Enregistrement et remise. Al-Ghonemy gère toutes les procédures de A à Z.",
