    areasCtaBtn: "Voir la Carte d'Accès et les Détails",
    faq6Q: "Comment protéger mes droits successoraux si les héritiers refusent le partage ?",
    faq6A: "Si les héritiers refusent le partage : 1) Déposer une action en partage forcé devant le Tribunal de la Famille, 2) Demander un expert judiciaire pour évaluer la succession, 3) Demander la vente du bien et partage du prix si le partage en nature impossible. Al-Ghonemy se spécialise dans les successions & héritages et obtient les meilleurs résultats.",
    faq7Q: "Quelles sont les étapes pour créer une entreprise en Égypte 2026 ?",
    faq7A: "Création d'entreprise en 2026 : 1) Choisir le type (Personne Unique, SARL, SA), 2) Réserver le nom commercial, 3) Préparer les statuts, 4) Déposer le capital à la banque, 5) S'inscrire au Registre du Commerce, 6) Obtenir la Carte Fiscale & Registre Commercial, 7) S'inscrire à l'Assurance Sociale. Al-Ghonemy finalise la création en 7-14 jours ouvrés.",
    faq8Q: "Comment contacter le Cabinet Al-Ghonemy ?",
    faq8A: "Vous pouvez nous contacter via : <strong>WhatsApp</strong> : <a href=\"https://wa.me/201126118276\">+20 112 611 8276</a>, <strong>Téléphone</strong> : <a href=\"tel:+201003651199\">+20 100 365 1199</a>, <strong>Email</strong> : <a href=\"mailto:alghoneimy.Law@gmail.com\">alghoneimy.Law@gmail.com</a>, <strong>Cabinet</strong> : Centre Al Hejaz – Près de la Place Al-Hosary – 6 Octobre – Giza. Nous travaillons tous les jours 17h - 22h.",
    svcCriminalBreadcrumb: "Affaires Pénales",
    svcCriminalTitle: "Affaires Pénales & Pourvois en Cassation",
    svcCriminalDesc: "Représentation devant le Tribunal du 6 Octobre, la Cour d'Appel de Giza, la Cour de Cassation. Contraventions, crimes, pourvois, défense forte.",
    svcCriminalContent1: "Les affaires pénales sont parmi les domaines juridiques les plus critiques nécessitant expertise et précision dans le traitement de chaque détail. Le Cabinet Al-Ghonemy fournit des services de représentation juridique devant les tribunaux pénaux et les grandes cours criminelles.",
    svcCriminalContent2: "Notre champ d'action comprend : les pourvois en cassation des jugements pénaux, la rédaction des mémoires de défense, l'étude des faits et documents, et la représentation des clients devant les tribunaux compétents.",
    svcCriminalContent3: "Nous traitons toutes les étapes de la procédure pénale, de l'enquête au jugement final, en assurant la défense la plus solide possible pour nos clients.",
