    svcCriminalArea4Service4: "Demandes de libération",
    svcCriminalFaqBadge: "FAQ - Affaires Pénales",
    svcCriminalFaqDesc: "Réponses rapides aux questions les plus fréquentes sur les affaires pénales",
    svcCriminalFaq1Q: "Quel est le délai légal pour le pourvoi en cassation ?",
    svcCriminalFaq1A: "Le pourvoi en cassation se forme dans un délai de 60 jours à compter de la date du jugement en matière pénale.",
    svcCriminalFaq2Q: "Peut-on constituer avocat après le jugement ?",
    svcCriminalFaq2A: "Oui, on peut constituer un avocat pour faire appel du jugement dans le délai légal.",
    svcCriminalFaq3Q: "Quelle est la différence entre contravention et crime ?",
    svcCriminalFaq3A: "La contravention est punie d'emprisonnement jusqu'à 3 ans ; le crime est puni de réclusion criminelle, de réclusion à perpétuité ou de la peine de mort.",
    svcCriminalFaq4Q: "Peut-on faire opposition à un jugement par défaut ?",
    svcCriminalFaq4A: "Oui, l'opposition au jugement par défaut peut être formée dans les 10 jours de sa signification.",
    svcCriminalFaq5Q: "Quelles sont les procédures d'enquête au parquet ?",
    svcCriminalFaq5A: "L'enquête comprend l'audition des déclarations, la confrontation des témoins et le transport sur les lieux. Le prévenu a droit au silence et droit à l'avocat.",
    svcCriminalFaq6Q: "Comment faire appel d'un jugement correctionnel ?",
    svcCriminalFaq6A: "L'appel se forme dans un délai de 10 jours du jugement, devant la Cour d'Appel de Giza.",
    svcCriminalFaq7Q: "Quels sont les droits du prévenu en enquête ?",
    svcCriminalFaq7A: "Droit au silence, droit à l'avocat, droit de ne pas s'auto-incriminer, droit de connaître la qualification des faits.",
    svcCriminalFaq8Q: "Servez-vous le Parquet du 6 Octobre ?",
    svcCriminalFaq8A: "Oui, nous comparaisons devant le Parquet Général et Partiel du 6 Octobre dans tous les types d'affaires pénales.",
    svcCriminalFaq9Q: "Qu'est-ce que la réconciliation pénale ?",
    svcCriminalFaq9A: "La réconciliation pénale est un mécanisme juridique pour résoudre certaines contraventions par accord des parties avec accord du tribunal.",
    svcCriminalCtaHeading: "Besoin d'un Avocat Pénal au 6 Octobre ou Giza ?",
    svcCriminalCtaSub: "19+ ans d'expérience en droit pénal et cassation - Avocats spécialisés pour une défense forte",
