    statRateLabel: "Taux de Succès en Contentieux",
    aboutBadge: "<i class=\"fas fa-gavel\"></i> À Propos",
    aboutTitle: "Un Cabinet avec une Vision Claire",
    aboutText1: "Le Cabinet Al-Ghonemy fournit des services juridiques dans toutes les spécialisations, avec une attention particulière à l'étude de chaque dossier individuellement et la compréhension de ses détails avant de définir le parcours juridique approprié.",
    aboutText2: "Nous combinons expertise juridique, recherche et rédaction précises, et gestion organisée des dossiers, aidant les clients à comprendre leur position juridique et à prendre des décisions sur une base claire.",
    aboutHighlight: "Nous ne donnons pas d'avis juridique général ; nous commençons par comprendre les détails de votre situation pour déterminer la solution et le parcours juridique les plus appropriés.",
    aboutCta: "En Savoir Plus",
