    svcFamilyContent1: "Les affaires familiales sont parmi les questions juridiques les plus sensibles car elles touchent directement la vie familiale. Nous fournissons des consultations et une représentation juridique dans toutes les affaires du Tribunal de la Famille.",
    svcFamilyContent2: "Nos services incluent : divorce, khul', pension, garde, visite, preuve de filiation, devant le Tribunal de la Famille du 6 Octobre. Nous traitons toutes les questions de statut personnel avec sensibilité et précision juridique.",
