    svcFamilyFaqDesc: "Réponses rapides aux questions les plus fréquentes sur les affaires familiales",
    svcFamilyFaq1Q: "Quel tribunal est compétent pour les affaires de pension ?",
    svcFamilyFaq1A: "Le Tribunal de la Famille compétent est le tribunal du domicile de l'épouse.",
    svcFamilyFaq2Q: "Le montant de la pension peut-il être modifié après jugement ?",
    svcFamilyFaq2A: "Oui, on peut intenter une action en modification de pension lors du changement de circonstances.",
    svcFamilyFaq3Q: "Quelle est la différence entre divorce et khul' ?",
    svcFamilyFaq3A: "Le divorce est initié par l'époux ; le khul' est initié par l'épouse avec restitution de la dot.",
    svcFamilyFaq4Q: "La garde peut-elle être modifiée après jugement ?",
    svcFamilyFaq4A: "Oui, la garde peut être modifiée lorsque l'intérêt supérieur de l'enfant l'exige.",
    svcFamilyFaq5Q: "Quels documents sont nécessaires pour le divorce ?",
    svcFamilyFaq5A: "Contrat de mariage, pièces d'identité, actes de naissance des enfants, et preuve de résidence.",
    svcFamilyFaq6Q: "Combien de temps dure une procédure de divorce ?",
    svcFamilyFaq6A: "Divorce par consentement mutuel : 1-3 mois ; divorce pour faute : 6-18 mois ; khul' : 3-6 mois.",
